import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

_DIRECTIVE = "@include"


def _expand(path, stack, included=False):
    real = os.path.realpath(path)
    if real in stack:
        raise ConfigError("include cycle detected at {}".format(path))
    try:
        with open(path, "r", encoding="utf-8") as fh:
            lines = fh.read().splitlines()
    except OSError as exc:
        if not included:
            raise
        raise ConfigError("cannot read include {}: {}".format(path, exc))
    base = os.path.dirname(os.path.abspath(path))
    stack = stack + (real,)
    out = []
    for raw in lines:
        parts = raw.split(None, 1)
        if parts and parts[0] == _DIRECTIVE:
            if len(parts) < 2 or not parts[1].strip():
                raise ConfigError("{}: @include requires a path".format(path))
            target = os.path.join(base, parts[1].strip())
            out.extend(_expand(target, stack, included=True))
        else:
            out.append(raw)
    return out


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced inline by the contents of the
    referenced file, resolved relative to the including file.
    """
    return parse_lines(_expand(path, ()))
